{"path":"assets/css/styles.css","content":"/* Minimal glass-morphism UI with gradient + SVG pattern background */
:root{
  --bg1:#0f1724;
  --bg2:#0b1220;
  --glass-bg:rgba(255,255,255,0.06);
  --glass-border:rgba(255,255,255,0.08);
  --accent:#a78bfa;
  --accent-2:#60a5fa;
  --muted:rgba(255,255,255,0.75);
  --radius:14px;
  --max-width:1100px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:var(--muted);background:linear-gradient(180deg,var(--bg1),var(--bg2));-webkit-font-smoothing:antialiased}
.site{min-height:100vh;display:flex;flex-direction:column}
body::before{content:'';position:fixed;inset:0;background-image:url('assets/img/pattern.svg');background-repeat:repeat;opacity:0.12;filter:blur(6px);z-index:0}
.nav-panel{position:sticky;top:0;z-index:10;padding:18px 20px}
.nav-inner{max-width:var(--max-width);margin:0 auto;display:flex;align-items:center;gap:16px}
.brand{display:flex;align-items:center;gap:12px;text-decoration:none;color:var(--muted)}
.logo-blob{width:46px;height:46px;background:linear-gradient(135deg,var(--accent),var(--accent-2));border-radius:12px;box-shadow:0 6px 20px rgba(15,23,36,0.6);flex:none}
.brand-text strong{display:block;color:#fff;font-size:16px}
.tagline{display:block;font-size:12px;opacity:0.86}
.main-nav{margin-left:auto}
.nav-toggle{background:transparent;border:1px solid var(--glass-border);color:var(--muted);padding:8px 12px;border-radius:10px}
.nav-list{list-style:none;margin:12px 0 0;padding:10px 12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px);border-radius:10px}
.nav-list li{margin:6px 0}
.nav-list a{color:var(--muted);text-decoration:none}
.nav-list a.cta{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#021124;padding:8px 12px;border-radius:8px}
.phone-link{margin-left:12px;color:var(--muted);text-decoration:none}
.page{max-width:var(--max-width);margin:28px auto;padding:0 20px;z-index:2}
.panel{margin:22px 0;padding:28px;border-radius:var(--radius);position:relative;border:1px solid var(--glass-border);background:var(--glass-bg);backdrop-filter:blur(8px)}
.panel .pattern{position:absolute;inset:0;width:100%;height:100%;opacity:0.06;pointer-events:none}
.hero{display:flex;align-items:center;justify-content:center;min-height:360px}
.hero-inner{max-width:780px;text-align:center}
.hero h1{color:#fff;margin:0 0 8px;font-size:28px}
.lead{opacity:0.95;margin:0 0 14px}
.hero-actions{display:flex;gap:12px;justify-content:center;margin-bottom:10px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;color:var(--muted);border:1px solid transparent}
.btn.primary{background:linear-gradient(90deg,var(--accent),var(--accent-2));color:#041229;border-color:transparent}
.btn.ghost{background:transparent;border:1px solid var(--glass-border)}
.btn.large{padding:14px 22px;font-size:16px}
.meta{font-size:13px;opacity:0.9}
.social .testimonials{display:grid;grid-template-columns:1fr 1fr 120px;gap:16px;align-items:center}
.test blockquote{margin:0;color:#fff;font-style:italic}
.test figcaption{margin-top:8px;font-size:13px;color:var(--muted)}
.stat{display:flex;flex-direction:column;align-items:center;justify-content:center}
.stat .num{font-size:28px;color:#fff}
.benefits .benefit-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.benefit-grid h3{color:#fff;margin:0 0 6px}
.process .process-steps{list-style:none;padding:0;margin:0;display:grid;gap:12px}
.process-steps li{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:12px;border-radius:10px}
.faq .faq-list details{background:transparent;padding:10px;border-radius:8px;margin-bottom:8px}
.faq summary{cursor:pointer;font-weight:600}
.lead-form{display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.lead-form input[type='email']{padding:10px;border-radius:8px;border:1px solid var(--glass-border);min-width:220px;background:transparent;color:var(--muted)}
.lead-form .small{font-size:12px;opacity:0.8;margin-top:8px}
.cta{display:flex;flex-direction:column;align-items:center;gap:10px}
.contact-small{font-size:13px;opacity:0.9}
.site-footer{margin-top:auto;padding:22px 20px}
.footer-inner{max-width:var(--max-width);margin:0 auto;display:flex;justify-content:space-between;align-items:center}
.footer-nav a{margin-left:12px;color:var(--muted);text-decoration:none}
@media (max-width:800px){
  .social .testimonials{grid-template-columns:1fr;}
  .benefit-grid{grid-template-columns:1fr}
  .nav-list{position:absolute;right:20px;top:64px}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // small UI behaviors: nav toggle, form capture, year insert
  document.addEventListener('DOMContentLoaded',function(){
    var toggle=document.getElementById('navToggle');
    var menu=document.getElementById('navMenu');
    if(toggle && menu){
      toggle.addEventListener('click',function(){
        var open=menu.hidden;
        menu.hidden=!open;
        toggle.setAttribute('aria-expanded',String(open));
      });
    }

    // year
    var y=document.getElementById('year');
    if(y) y.textContent=(new Date()).getFullYear();

    // lead form: basic validation and local storage (no external calls)
    var leadForm=document.getElementById('leadForm');
    if(leadForm){
      leadForm.addEventListener('submit',function(e){
        e.preventDefault();
        var email=leadForm.querySelector('input[name="email"]').value.trim();
        if(!email || email.indexOf('@')===-1){
          alert('Please enter a valid email to receive the guide.');
          return;
        }
        try{localStorage.setItem('aroma_lead',JSON.stringify({email:email,t:Date.now()}));}catch(err){}
        // visual confirmation
        leadForm.innerHTML='<p class="lead-confirm">Thanks — check your inbox for the Quick-Start Guide. If you do not receive it, contact us at {{EMAIL}}.</p>';
      });
    }

    // accessible details polyfill: ensure only keyboard accessible focus states
    var details=document.querySelectorAll('details');
    details.forEach(function(d){
      d.addEventListener('toggle',function(){
        // no-op but keeps behavior consistent across browsers
      });
    });
  });
})();
"} 
